package es.vargontoc.storyteller.application.service;
import java.util.Optional;
import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import es.vargontoc.storyteller.application.ports.in.character.CharacterReviewUseCase; import es.vargontoc.storyteller.application.ports.out.external.CharacterAgent; import es.vargontoc.storyteller.application.ports.out.external.CharacterImageConditionPort; import es.vargontoc.storyteller.domain.command.CatalogCharacterReviewCommand; import es.vargontoc.storyteller.domain.enums.CharacterReviewTarget; import es.vargontoc.storyteller.domain.enums.RevisionStatus; import es.vargontoc.storyteller.domain.model.ActorMetadata; import es.vargontoc.storyteller.domain.request.CatalogCharacterReviewAgentRequest; import es.vargontoc.storyteller.domain.response.CatalogCharacterReviewAgentResult; import es.vargontoc.storyteller.infrastructure.persistence.*; import es.vargontoc.storyteller.shared.exceptions.AppException;
@Service public class CharacterReviewService implements CharacterReviewUseCase {
 private final CharacterAgent agent; private final CatalogCharacterJpaRepository characters; private final CatalogCharacterReviewJpaRepository reviews; private final Optional<CharacterImageConditionPort> images;
 public CharacterReviewService(CharacterAgent agent,CatalogCharacterJpaRepository characters,CatalogCharacterReviewJpaRepository reviews,Optional<CharacterImageConditionPort> images){this.agent=agent;this.characters=characters;this.reviews=reviews;this.images=images;}
 @Transactional public CatalogCharacterReviewAgentResult request(CatalogCharacterReviewCommand c){var character=characters.findById(c.catalogCharacterId()).orElseThrow(()->new AppException("Catálogo no encontrado",HttpStatus.NOT_FOUND));var previous=reviews.findByCatalogCharacterIdAndStatus(c.catalogCharacterId(),RevisionStatus.PENDING);if(previous.isPresent()&&!c.replacePending())throw new AppException("Existe una revisión pendiente; confirme su reemplazo",HttpStatus.CONFLICT);if(c.target()!=CharacterReviewTarget.NARRATIVE){var image=images.orElseThrow(()->new AppException("La condición de imágenes no está disponible",HttpStatus.SERVICE_UNAVAILABLE)); image.hasGeneratedImages(c.catalogCharacterId());}var m=character.getMetadata();var result=agent.review(new CatalogCharacterReviewAgentRequest(character.getName(),character.getNarrativeDescription(),character.getVisualDescription(),m.translate(),m.attributes(),c.target(),c.hint()));if(!result.accepted())return result;previous.ifPresent(p->{p.setStatus(RevisionStatus.DISCARDED);reviews.save(p);});var entity=new CatalogCharacterReviewJpaEntity();entity.setCatalogCharacter(character);entity.setStatus(RevisionStatus.PENDING);entity.setTarget(c.target());entity.setHint(c.hint());entity.setCandidateName(result.name());entity.setCandidateNarrative(result.narrativeDescription());entity.setCandidateVisual(result.visualDescription());entity.setMetadata(new ActorMetadata(result.visualDescriptionEn(),result.visualAttributes()));reviews.save(entity);return result;}
 public es.vargontoc.storyteller.domain.response.CatalogCharacterReviewView getPending(Long id){var r=reviews.findByCatalogCharacterIdAndStatus(id,RevisionStatus.PENDING).orElseThrow(()->new AppException("No existe revisión pendiente",HttpStatus.NOT_FOUND));return new es.vargontoc.storyteller.domain.response.CatalogCharacterReviewView(r.getId(),r.getTarget(),r.getHint(),r.getCandidateName(),r.getCandidateNarrative(),r.getCandidateVisual());}
}
